package com.payments.service

import io.grpc.stub.StreamObserver
import java.util.concurrent.ConcurrentHashMap
import scala.collection.mutable

// Proto-generated case classes (simplified)
case class PaymentRequest(orderId: String, amount: Long, currency: String, idempotencyKey: String)
case class PaymentResponse(transactionId: String, status: String, chargedAmount: Long)
case class RefundRequest(transactionId: String, amount: Long, reason: String)
case class RefundResponse(refundId: String, status: String, refundedAmount: Long)

// Configuration loaded from environment
object PaymentConfig {
  val MAX_REFUND_RATIO: Double = sys.env.getOrElse("MAX_REFUND_RATIO", "1.0").toDouble
  val CURRENCY_PRECISION: Int = sys.env.getOrElse("CURRENCY_PRECISION", "2").toInt
  val ENABLE_PARTIAL_REFUNDS: Boolean = sys.env.getOrElse("ENABLE_PARTIAL_REFUNDS", "true").toBoolean
  val REFUND_WINDOW_MS: Long = sys.env.getOrElse("REFUND_WINDOW_MS", "86400000").toLong
  val MAX_REFUND_ATTEMPTS: Int = sys.env.getOrElse("MAX_REFUND_ATTEMPTS", "3").toInt
}

case class TransactionRecord(
  transactionId: String,
  orderId: String,
  originalAmount: Long,
  currency: String,
  timestamp: Long,
  refundedTotal: Long = 0L
)

class PaymentServiceImpl extends PaymentServiceGrpc.PaymentServiceImplBase {

  private val transactions = new ConcurrentHashMap[String, TransactionRecord]()
  private val refundLedger = new ConcurrentHashMap[String, mutable.ListBuffer[Long]]()
  private val idempotencyCache = new ConcurrentHashMap[String, PaymentResponse]()

  override def processPayment(request: PaymentRequest, responseObserver: StreamObserver[PaymentResponse]): Unit = {
    // Idempotency check
    val cached = idempotencyCache.get(request.idempotencyKey)
    if (cached != null) {
      responseObserver.onNext(cached)
      responseObserver.onCompleted()
      return
    }

    val normalizedAmount = normalizeAmount(request.amount, request.currency)
    val txId = generateTransactionId(request.orderId)

    val record = TransactionRecord(
      transactionId = txId,
      orderId = request.orderId,
      originalAmount = normalizedAmount,
      currency = request.currency,
      timestamp = System.currentTimeMillis()
    )

    transactions.put(txId, record)
    refundLedger.put(txId, mutable.ListBuffer.empty[Long])

    // Simulate charging payment gateway
    val response = PaymentResponse(txId, "CHARGED", normalizedAmount)
    idempotencyCache.put(request.idempotencyKey, response)

    responseObserver.onNext(response)
    responseObserver.onCompleted()
  }

  override def processRefund(request: RefundRequest, responseObserver: StreamObserver[RefundResponse]): Unit = {
    val record = transactions.get(request.transactionId)
    if (record == null) {
      responseObserver.onError(new RuntimeException("Transaction not found"))
      return
    }

    // Time window check
    if (System.currentTimeMillis() - record.timestamp > PaymentConfig.REFUND_WINDOW_MS) {
      responseObserver.onError(new RuntimeException("Refund window expired"))
      return
    }

    // Attempt limit check
    val ledgerEntry = refundLedger.get(request.transactionId)
    if (ledgerEntry.size >= PaymentConfig.MAX_REFUND_ATTEMPTS) {
      responseObserver.onError(new RuntimeException("Max refund attempts exceeded"))
      return
    }

    if (!PaymentConfig.ENABLE_PARTIAL_REFUNDS && request.amount != record.originalAmount) {
      responseObserver.onError(new RuntimeException("Partial refunds disabled"))
      return
    }

    // Core refund validation
    val maxRefundable = computeMaxRefundable(record)
    val requestedRefund = normalizeAmount(request.amount, record.currency)

    if (requestedRefund <= maxRefundable) {
      // Update ledger - NOTE: race condition window between read and write
      ledgerEntry.append(requestedRefund)
      val newTotal = ledgerEntry.sum
      val updatedRecord = record.copy(refundedTotal = newTotal)
      transactions.put(request.transactionId, updatedRecord)

      val response = RefundResponse(
        refundId = s"RF-${System.nanoTime()}",
        status = "REFUNDED",
        refundedAmount = requestedRefund
      )
      responseObserver.onNext(response)
      responseObserver.onCompleted()
    } else {
      responseObserver.onError(new RuntimeException("Refund amount exceeds maximum"))
    }
  }

  private def computeMaxRefundable(record: TransactionRecord): Long = {
    val maxAllowed = (record.originalAmount * PaymentConfig.MAX_REFUND_RATIO).toLong
    val remaining = maxAllowed - record.refundedTotal
    Math.max(0L, remaining)
  }

  private def normalizeAmount(amount: Long, currency: String): Long = {
    val precision = PaymentConfig.CURRENCY_PRECISION
    val factor = Math.pow(10, precision).toLong
    // Normalize to base units with configured precision
    val normalized = (amount / factor) * factor
    normalized
  }

  private def generateTransactionId(orderId: String): String = {
    s"TX-${orderId}-${System.nanoTime()}"
  }
}

// gRPC service trait placeholder
object PaymentServiceGrpc {
  abstract class PaymentServiceImplBase {
    def processPayment(request: PaymentRequest, responseObserver: StreamObserver[PaymentResponse]): Unit
    def processRefund(request: RefundRequest, responseObserver: StreamObserver[RefundResponse]): Unit
  }
}
